SKILLS_ZH["2118561861109203322"] = {"title": "开发者转向 Claude Code 桌面端，对比 Codex 口碑升温", "summary": "Claude Code 桌面端支持可视化 diff、内置终端与并行会话；社区 SDK 与 loopy 等项目把它做成自治 Agent。Codex 在部分场景更快，但多文件推理与活跃迭代更受青睐。", "hook": "开发者们正在注意到他们日常编码工具的真正变化。", "category": "Agent / 编程"}
SKILLS_ZH["2117902210726305919"] = {"title": "Codex 在「电脑操控」上领先，Claude Code 深耕终端推理", "summary": "社区对比：Codex 更擅长直接点选 UI、操作无 API 的遗留软件；Claude Code 更强终端与深度改码。多数人认为两者互补。", "hook": "开发者称赞 Codex 能像人类一样应对复杂的用户界面。", "category": "Agent / 编程"}
SKILLS_ZH["2117768217288400999"] = {"title": "Anthropic 把 Claude Code 子 Agent 后台成本砍掉约 99%", "summary": "状态栏刷新改由 Haiku 5.5 根据短笔记生成，不再每 30 秒重读整段对话；更新到 v2.1.316+ 后 Pro/Max 等用户可用，会话效率约再升 6%。", "hook": "使用 Claude Code 构建的开发者在代币成本上刚刚获得了巨大的优惠。", "category": "产品更新"}
SKILLS_ZH["2118441513608753167"] = {"title": "AI 恐怖短片：超市夜班掉进无限分身迷宫", "summary": "创作者用 Flova 1.5 的极限空间技能扭曲货架，Multi-View Character 保持分身一致，低成本做出不安感强的迷你恐怖片。", "hook": "人工智能创作者将诡异的超市克隆迷宫变为现实。", "category": "视频生成"}
SKILLS_ZH["2118068699252801836"] = {"title": "商汤 SenseNova 6.8：长记忆 + 可编辑 PPT/网站/3D", "summary": "Flash 版强调跨对话记住目标与约束，可出动画 PPT、动效海报、交互站与 Blender 工程；开源 Code2Video，Raccoon 助手限免至 12 月 1 日。", "hook": "商汤科技的最新模型能够在聊天中记住项目目标。", "category": "模型发布"}
