SKILLS_ZH["2118110195176157443"] = {"title": "网红吐槽：Instagram 私信另一头其实是 Claude", "summary": "Clavicular 一条调侃引爆讨论，科技圈跟风玩梗；侧面说明 Agent 已渗入社媒运营与营销自动化。", "hook": "锁骨叫出一个在展示他 Instagram 私信的女人——她正在和克劳德聊天。", "category": "Agent / 社会"}
SKILLS_ZH["2118351763493253454"] = {"title": "彩色光标蜂群协作重建网页：多 Agent 演示刷屏", "summary": "Swarm Rebuild 等扩展让一群光标分工画框、打字、拼布局；兴奋于一人公司放大，也有人抱怨要读的模型输出比以往更多。", "hook": "数十个动画光标在屏幕上跳动，重建一个网页。", "category": "Agent / 演示"}
SKILLS_ZH["2118200427053260808"] = {"title": "Oumi 发布 FAiE：用自然语言自动打造定制 AI Agent", "summary": "Frontier AI Engineer 可在约 15 分钟人工输入后，自动完成评测、失败诊断、数据策展与训练，几小时内交付带权重的专用模型与 Agent 工具链。", "hook": "想象一下，用简单的话描述一个任务，然后几个小时后就能得到一个可以直接使用的 AI 代理。", "category": "Agent / 工具"}
